appearances.css:
.app{display:flex;flex-direction:column;gap:4px;padding:6px;border-radius:4px;font-size:9px}
.top{display:flex;flex-wrap:wrap;gap:4px 5px;margin:0;align-items:flex-end;border:1px solid var(--line,#39424e);border-radius:4px;padding:4px 5px}
.sel{flex-direction:column-reverse;align-items:center;gap:1px;font-size:7.5px;letter-spacing:0;text-align:center}
.top select,.top button,.edtop select,.edtop button,.edtop input[type=text]{font-size:8.5px;padding:3px 5px;border-radius:3px}
.patbtns button{min-width:22px;padding:3px 0}
.stt{display:none}
.rows{gap:2px}
.row{grid-template-columns:96px 22px 22px minmax(0,1fr) 36px;gap:3px}
.nm{height:20px;padding:0 4px;font-size:9px;gap:4px}
.nm small{font-size:7.5px}
.ms{padding:2px 0;font-size:9px;height:20px}
.steps{gap:2px}
.st{height:20px;font-size:7.5px;border-radius:2px}
.len select{padding:2px 0 2px 3px;width:100%;font-size:9px;height:20px}
.ed{margin-top:0;border-top:0;padding-top:0;display:flex;flex-wrap:wrap;gap:4px}
.ed>*{flex:1 1 100%}
.edtop{border:1px solid var(--line,#39424e);border-radius:4px;padding:4px 5px;gap:4px 5px}
.edtop input[type=text]{width:84px}
canvas{height:28px!important;border-radius:3px;width:1px!important;min-width:100%}
h3{display:none}
.grid{display:flex;flex-wrap:nowrap;gap:2px;border:1px solid var(--line,#39424e);border-radius:4px;padding:4px 4px 3px;margin:0}
.grid:nth-of-type(2){flex:4.6 1 0}
.grid:nth-of-type(3){flex:3 1 0}
.grid:nth-of-type(4){flex:4 1 0}
.grid:nth-of-type(5){flex:3 1 0}
.c{flex:1 1 0;display:grid;grid-template-columns:minmax(0,1fr);justify-items:center;align-items:start;gap:0;min-width:0}
.c .lab{display:contents}
.c .lab span{order:3;font-size:7px;text-align:center;line-height:1.1;max-width:100%;letter-spacing:-.02em;text-transform:none;overflow-wrap:normal}
.c .lab output{order:2;font-size:8px;line-height:1.1;text-align:center;white-space:nowrap;letter-spacing:-.04em}
.c>.kn{order:1;width:26px!important;height:26px!important;justify-self:center!important}
.c .kn svg{width:100%;height:100%}
.swrow{gap:0;flex-direction:column;align-items:center}
.swrow>.kn,.sel>.kn{width:26px!important;height:26px!important}
.swrow output{order:2;font-size:8px;text-align:center;min-width:0}
.swrow>.kn{order:1}
.sel>.kn{order:1}
.top select{max-width:96px}
.top>.sel:nth-child(1) select{max-width:80px}
